      if (!contractsAll().length) h += '<div class="dc-card"><div class="body"><b>No offer on the table</b><small>' + (!unlocked('contracts') ? 'Reach level ' + UNLOCK.contracts + '.' : 'Next offer around day ' + S.nextOffer + '.') + '</small></div></div>';
