  GAME.shadowLive = function () { return driving || (S.agv && S.agv.state !== 'idle' && S.up.agv) || S.trucks.some(function (t) { return (t.state === 'coming' || t.state === 'leaving') && dist2(t.x, t.z, player.x, player.z) < 60 * 60; }); };

